```tsx
import { useEffect, useRef, useState } from 'react';
import type { CSSProperties } from 'react';

type Shape = {
  color: string;
  width: number;
  height: number;
  top: string;
  left: string;
  radius: string;
  mix: number;
  delay: string;
  duration: string;
};

/* One shape set per page scene; scrolling between sections swaps the sets. */
const scenes: Shape[][] = [...];

const sceneIds = ['top', 'preview', 'features', 'install', 'roadmap', 'links'];

const LEAVE_MS = 900;

function ShapeLayer({ shapes, leaving }: { shapes: Shape[]; leaving: boolean }) {
  return (
    <div className={`backdrop__layer ${leaving ? 'is-leaving' : 'is-entering'}`}>
      {shapes.map((shape, index) => (
        <span
          key={index}
          className="backdrop__flight"
          style={{ '--t': shape.top, '--l': shape.left, '--stagger': `${index * 70}ms` } as CSSProperties}
        >
          <span
            className="backdrop__shape"
            style={{
              '--c': shape.color,
              '--w': `${shape.width}px`,
              '--h': `${shape.height}px`,
              '--r': shape.radius,
              '--mix': `${shape.mix}%`,
              '--delay': shape.delay,
              '--dur': shape.duration,
            } as CSSProperties}
          />
        </span>
      ))}
    </div>
  );
}

export function Backdrop() {
  const [current, setCurrent] = useState(0);
  const [previous, setPrevious] = useState<number | null>(null);
  const currentRef = useRef(0);
  const reducedRef = useRef(false);

  useEffect(() => {
    const query = window.matchMedia('(prefers-reduced-motion: reduce)');
    reducedRef.current = query.matches;
    const onChange = (event: MediaQueryListEvent) => {
      reducedRef.current = event.matches;
    };
    query.addEventListener('change', onChange);

    let frame = 0;
    const measure = () => {
      frame = 0;
      const line = window.innerHeight * 0.42;
      let next = 0;
      sceneIds.forEach((id, index) => {
        const node = document.getElementById(id);
        if (node && node.getBoundingClientRect().top <= line) next = index;
      });
      if (next === currentRef.current) return;
      if (!reducedRef.current) setPrevious(currentRef.current);
      currentRef.current = next;
      setCurrent(next);
    };
    const onScroll = () => {
      if (frame) return;
      frame = requestAnimationFrame(measure);
    };

    measure();
    window.addEventListener('scroll', onScroll, { passive: true });
    window.addEventListener('resize', onScroll);
    return () => {
      cancelAnimationFrame(frame);
      window.removeEventListener('scroll', onScroll);
      window.removeEventListener('resize', onScroll);
      query.removeEventListener('change', onChange);
    };
  }, []);

  useEffect(() => {
    if (previous === null) return;
    const timer = window.setTimeout(() => setPrevious(null), LEAVE_MS);
    return () => window.clearTimeout(timer);
  }, [previous]);

  return (
    <div className="backdrop" aria-hidden="true">
      {previous !== null && previous !== current ? (
        <ShapeLayer key={`out-${previous}`} shapes={scenes[previous]} leaving />
      ) : null}
      <ShapeLayer key={current} shapes={scenes[current]} leaving={false} />
    </div>
  );
}
