type LayerProps = {
  shapes: Shape[];
  leaving?: boolean;
};

function ShapeLayer({ shapes, leaving = false }: LayerProps) {
  return (
    <div className={`backdrop__layer ${leaving ? 'is-leaving' : 'is-entering'}`}>
      {shapes.map((shape, index) => (
        <span
          key={index}
          className="backdrop__flight"
          style={
