.backdrop__layer {
  position: absolute;
  inset: 0;
}

/* each shape travels with its own scene layer */
.backdrop__flight {
  position: absolute;
  top: var(--t);
  left: var(--l);
  animation: backdrop-in 0.85s var(--ease-out) both;
  animation-delay: var(--stagger, 0ms);
  will-change: transform, opacity;
}

.backdrop__layer.is-leaving .backdrop__flight {
  animation: backdrop-out 0.62s var(--ease-in-out) both;
  animation-delay: calc(var(--stagger, 0ms) * 0.35);
}

@keyframes backdrop-in {
  from {
    opacity: 0;
    transform: translate3d(0, 90px, 0) scale(0.94);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

@keyframes backdrop-out {
  from {
    opacity: 1;
    transform: none;
  }
  to {
    opacity: 0;
    transform: translate3d(0, -130px, 0) scale(1.06);
  }
}

.backdrop__shape {
  display: block;
  width: var(--w);
  height: var(--h);
  border-radius: var(--r, 50%);
  background: color-mix(in oklab, var(--c) var(--mix, 10%), transparent);
  opacity: 0;
  animation: shape-rise var(--dur, 42s) var(--ease-in-out) infinite;
  animation-delay: var(--delay, 0s);
  will-change: transform, opacity;
}

