  const r = el.getBoundingClientRect();
  const px = r.left + r.width * 0.2, py = r.top + r.height * 0.25;
  el.dispatchEvent(new PointerEvent('pointermove', {clientX: px, clientY: py, pointerType:'mouse', bubbles:true}));
  await new Promise(r => requestAnimationFrame(() => requestAnimationFrame(r)));
  const hover = { mx: el.style.getPropertyValue('--mx'), my: el.style.getPropertyValue('--my'), glow: getComputedStyle(el, '::after').opacity };
  el.dispatchEvent(new PointerEvent('pointerleave', {pointerType:'mouse', bubbles:true}));
  await new Promise(r => setTimeout(r, 100));
  const mid = { mx: el.style.getPropertyValue('--mx'), my: el.style.getPropertyValue('--my'), glow: getComputedStyle(el, '::after').opacity };
  await new Promise(r => setTimeout(r, 400));
  const after = { mx: el.style.getPropertyValue('--mx') || '(none)', my: el.style.getPropertyValue('--my') || '(none)', glow: getComputedStyle(el, '::after').opacity };
  return { hover, mid, after };
})()` });
return res.value;

