const tabID = "tab_da8a743f-8285-4d9d-8787-a6914608ecb6";
await tools.browser.navigate({ tabID, url: "http://localhost:5174/" });
const res = await tools.browser.evaluate({ tabID, script: `(async () => {
  await new Promise(r => setTimeout(r, 900));
  const el = document.getElementById('links');
  el.scrollIntoView({behavior:'instant', block:'start'});
  await new Promise(r => setTimeout(r, 250));
  const cards = [...document.querySelectorAll('.link-card')];
  const cells = [...document.querySelectorAll('.link-cell')];
  const tilts = [...document.querySelectorAll('.link-cell .card-tilt')];
  const rect = el => { const r = el.getBoundingClientRect(); return [Math.round(r.x), Math.round(r.y), Math.round(r.width), Math.round(r.height)]; };
  return {
    grid: rect(document.querySelector('.links-grid')),
    cells: cells.map(rect),
    tilts: tilts.map(rect),
    cards: cards.map(rect),
    cellStyle: cells.map(c => { const s = getComputedStyle(c); return [s.display, s.alignItems, s.height]; }),
  };
})()` });
return res.value;

