const res = await tools.browser.evaluate({ tabID, script: `(() => {
  const card = document.querySelector('.install-card');
  const stage = document.querySelector('.install-stage');
  const cs = getComputedStyle(card);
  const ss = getComputedStyle(stage);
  return {
    card: { transform: cs.transform, marginTop: cs.marginTop, position: cs.position, animation: cs.animationName, display: cs.display },
    stage: { overflow: ss.overflow, height: ss.height, padding: ss.padding, display: ss.display },
    cardAnims: card.getAnimations().map(a => ({name: a.animationName, playState: a.playState, currentTime: a.currentTime})),
  };
})()` });
return res.value;

